#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct { float x, y, z; } Vec3;
typedef struct { Vec3 origin, dir; } Ray;

Vec3 v_add(Vec3 a, Vec3 b) { return (Vec3){a.x+b.x, a.y+b.y, a.z+b.z}; }
Vec3 v_sub(Vec3 a, Vec3 b) { return (Vec3){a.x-b.x, a.y-b.y, a.z-b.z}; }
Vec3 v_mul(Vec3 a, float t) { return (Vec3){a.x*t, a.y*t, a.z*t}; }
Vec3 v_cross(Vec3 a, Vec3 b) { return (Vec3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x}; }
float v_dot(Vec3 a, Vec3 b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
Vec3 v_norm(Vec3 a) { float l = sqrt(v_dot(a,a)); return v_mul(a, 1.0f/l); }

typedef struct {
    Vec3 center;
    float radius;
    Vec3 color;
    int type; // 0=sphere, 1=ground
} Obj;

int sphere_hit(Vec3 ro, Vec3 rd, Vec3 c, float r, float *t, Vec3 *n) {
    Vec3 oc = v_sub(ro, c);
    float a = v_dot(rd, rd);
    float b = 2.0f * v_dot(oc, rd);
    float cc = v_dot(oc, oc) - r*r;
    float disc = b*b - 4*a*cc;
    if (disc < 0) return 0;
    float t1 = (-b - sqrt(disc)) / (2*a);
    if (t1 > 0.001f) {
        *t = t1;
        Vec3 p = v_add(ro, v_mul(rd, t1));
        *n = v_norm(v_sub(p, c));
        return 1;
    }
    return 0;
}

int ground_hit(Vec3 ro, Vec3 rd, float *t, Vec3 *n, Vec3 *col) {
    if (rd.y > -0.001f) return 0;
    float tt = -ro.y / rd.y;
    if (tt < 0.001f) return 0;
    *t = tt;
    *n = (Vec3){0, 1, 0};
    Vec3 p = v_add(ro, v_mul(rd, tt));
    int cx = (int)(p.x * 0.5f) & 1;
    int cz = (int)(p.z * 0.5f) & 1;
    float gray = (cx ^ cz) ? 0.6f : 0.267f;
    *col = (Vec3){gray, gray, gray};
    return 1;
}

Vec3 trace(Vec3 ro, Vec3 rd, int depth) {
    if (depth > 3) return (Vec3){0, 0, 0};

    float t_sphere = 1e9, t_ground = 1e9;
    Vec3 n_sphere, n_ground, ground_col;
    int hit_s = 0, hit_g = 0;

    hit_s = sphere_hit(ro, rd, (Vec3){0, 0.5f, -3}, 0.5f, &t_sphere, &n_sphere);
    hit_g = ground_hit(ro, rd, &t_ground, &n_ground, &ground_col);

    if (!hit_s && !hit_g) {
        float t = 0.5f * (rd.y + 1.0f);
        return v_add(v_mul((Vec3){0.623f, 0.773f, 1.0f}, 1.0f - t),
                     v_mul((Vec3){0.584f, 0.761f, 1.0f}, t));
    }

    if (hit_s && t_sphere < t_ground) {
        Vec3 p = v_add(ro, v_mul(rd, t_sphere));
        Vec3 light_dir = v_norm((Vec3){1, 1, -2});
        float diff = fmax(0.0f, v_dot(n_sphere, light_dir));
        Vec3 sphere_col = (Vec3){0.2f, 0.039f, 0.039f};
        Vec3 c = v_mul(sphere_col, 0.3f + 0.7f * diff);
        Vec3 reflect_dir = v_sub(rd, v_mul(n_sphere, 2.0f * v_dot(rd, n_sphere)));
        c = v_add(c, v_mul(trace(p, reflect_dir, depth+1), 0.3f));
        return c;
    }

    if (hit_g) {
        Vec3 p = v_add(ro, v_mul(rd, t_ground));
        Vec3 light_dir = v_norm((Vec3){1, 1, -2});
        float diff = fmax(0.0f, v_dot(n_ground, light_dir));
        Vec3 c = v_mul(ground_col, 0.5f + 0.5f * diff);
        Vec3 reflect_dir = v_sub(rd, v_mul(n_ground, 2.0f * v_dot(rd, n_ground)));
        c = v_add(c, v_mul(trace(p, reflect_dir, depth+1), 0.2f));
        return c;
    }

    return (Vec3){0, 0, 0};
}

int main() {
    int W = 2400, H = 1800;
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", W, H);

    Vec3 cam_pos = (Vec3){0, 1, 2};

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            float u = (x - W/2.0f) / (H/2.0f);
            float v = (H/2.0f - y) / (H/2.0f);
            Vec3 rd = v_norm((Vec3){u * 1.2f, v * 1.2f, -1.0f});
            Vec3 col = trace(cam_pos, rd, 0);
            int r = (int)(fmax(0, fmin(1, col.x)) * 255);
            int g = (int)(fmax(0, fmin(1, col.y)) * 255);
            int b = (int)(fmax(0, fmin(1, col.z)) * 255);
            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    return 0

